def cross_correlate(signal, kernel):
    return [sum(signal[i+j]*w for j,w in enumerate(kernel))
            for i in range(len(signal)-len(kernel)+1)]

def box_area(box):
    x1, y1, x2, y2 = box
    return (x2-x1) * (y2-y1)

def global_average(channels):
    output = []
    for plane in channels:
        values = [v for row in plane for v in row]
        output.append(sum(values)/len(values))
    return output
